/* Generated from tokens.ts by scripts/build-tokens.ts. Do not edit by hand. */
@layer atlas.tokens, atlas.base, atlas.components, atlas.site;

@layer atlas.tokens {
  :root {
    --font-ui: 'Bricolage Grotesque', 'Bricolage Fallback', ui-sans-serif, system-ui, sans-serif;
    --font-prose: 'Newsreader', 'Newsreader Fallback', ui-serif, Georgia, serif;
    --font-code: 'JetBrains Mono', ui-monospace, 'Cascadia Mono', Consolas, monospace;
    --step-0: 1.0625rem;
    --step-1: 1.328rem;
    --step-2: 1.66rem;
    --step-3: 2.075rem;
    --step-4: 2.594rem;
    --step-5: 3.242rem;
    --step-6: 4.053rem;
    --step--1: 0.85rem;
    --leading-ui: 1.45;
    --leading-prose: 1.6;
    --leading-tight: 1.08;
    --measure: 68ch;
    --space-3xs: 0.125rem;
    --space-2xs: 0.25rem;
    --space-xs: 0.5rem;
    --space-s: 0.75rem;
    --space-m: 1rem;
    --space-l: 1.5rem;
    --space-xl: 2rem;
    --space-2xl: 3rem;
    --space-3xl: 4rem;
    --space-4xl: 6rem;
    --space-5xl: 8rem;
    --radius-control: 6px;
    --radius-panel: 12px;
    --radius-overlay: 16px;
    --radius-round: 999px;
    --target-min: 24px;
    --target-comfort: 44px;
    --ease-anchor: cubic-bezier(0.2, 0, 0, 1);
    --ease-drift: cubic-bezier(0.22, 0.61, 0.24, 1);
    --ease-ebb: cubic-bezier(0.4, 0, 1, 1);
    --ease-current: linear(0, 0.0361, 0.1287, 0.2445, 0.3793, 0.5052, 0.6222, 0.7316, 0.8183, 0.8926, 0.9466, 0.9886, 1.0159, 1.0334, 1.0435, 1.047, 1.0462, 1.0427, 1.0376, 1.0313, 1.0253, 1.0193, 1.0142, 1.0099, 1.0061, 1.0033, 1.0011, 0.9996, 0.9987, 0.9981, 0.9978, 0.9978, 0.9979, 0.9982, 0.9984, 0.9987, 0.999, 0.9993, 0.9995, 1);
    --dur-tick: 90ms;
    --dur-step: 160ms;
    --dur-glide: 280ms;
    --dur-voyage: 560ms;
    --dur-current: 640ms;
    --sea: var(--sea-0);
    --magenta-wash: color-mix(in oklch, var(--chart-magenta) 16%, transparent);
    --ink-wash: color-mix(in oklch, var(--ink) 7%, transparent);
    --ink-wash-strong: color-mix(in oklch, var(--ink) 13%, transparent);
    --focus-ring: 2px solid var(--chart-magenta);
    --focus-offset: 2px;
    --elev-gap: var(--sea);
    --elev-1: 0 0 0 1px color-mix(in oklch, var(--isobath) 70%, transparent), 0 0 0 4px var(--elev-gap), 0 0 0 5px color-mix(in oklch, var(--isobath) 30%, transparent);
    --elev-2: 0 0 0 1px var(--edge), 0 0 0 4px var(--elev-gap), 0 0 0 5px color-mix(in oklch, var(--isobath) 45%, transparent);
    --elev-overlay: 0 0 0 1px color-mix(in oklch, var(--edge) 60%, transparent), 0 2px 4px var(--shadow-tint), 0 24px 56px -16px var(--shadow-tint);
  }

  :root,
  [data-theme='night'] {
    color-scheme: dark;
    --sea-0: #0E1E2B;
    --sea-1: #0C1A26;
    --sea-2: #0A1721;
    --sea-3: #09141D;
    --shoal: #15293A;
    --reef: #1D3A4C;
    --ink: #DCE6E4;
    --ink-soft: #9DB4B8;
    --edge: #6F98A4;
    --isobath: #4F7C88;
    --chart-magenta: #E683C6;
    --on-magenta: #0E1E2B;
    --starboard: #74D3A0;
    --port: #F2907F;
    --caution: #E9BD68;
    --shadow-tint: color-mix(in oklch, #02080D 72%, transparent);
  }

  @media (prefers-color-scheme: light) {
    :root:not([data-theme]) {
      color-scheme: light;
      --sea-0: #EEF3F1;
      --sea-1: #E8F0EF;
      --sea-2: #E2ECEC;
      --sea-3: #DDE8E9;
      --shoal: #DFEBEC;
      --reef: #CBDFE3;
      --ink: #15283A;
      --ink-soft: #465D6D;
      --edge: #5E7F89;
      --isobath: #7FA0A8;
      --chart-magenta: #A0186C;
      --on-magenta: #FFFFFF;
      --starboard: #1E6A46;
      --port: #A4322A;
      --caution: #765000;
      --shadow-tint: color-mix(in oklch, #15283A 22%, transparent);
    }
  }

  [data-theme='day'] {
    color-scheme: light;
    --sea-0: #EEF3F1;
    --sea-1: #E8F0EF;
    --sea-2: #E2ECEC;
    --sea-3: #DDE8E9;
    --shoal: #DFEBEC;
    --reef: #CBDFE3;
    --ink: #15283A;
    --ink-soft: #465D6D;
    --edge: #5E7F89;
    --isobath: #7FA0A8;
    --chart-magenta: #A0186C;
    --on-magenta: #FFFFFF;
    --starboard: #1E6A46;
    --port: #A4322A;
    --caution: #765000;
    --shadow-tint: color-mix(in oklch, #15283A 22%, transparent);
  }

  @media (prefers-reduced-motion: reduce) {
    :root:not([data-motion='full']) {
      --dur-tick: 0ms;
      --dur-step: 0ms;
      --dur-glide: 0ms;
      --dur-voyage: 0ms;
      --dur-current: 0ms;
    }
  }

  :root[data-motion='reduce'] {
    --dur-tick: 0ms;
    --dur-step: 0ms;
    --dur-glide: 0ms;
    --dur-voyage: 0ms;
    --dur-current: 0ms;
  }
}

@layer atlas.base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
    background: var(--sea);
    color: var(--ink);
    font-family: var(--font-ui);
    font-size: 100%;
    line-height: var(--leading-ui);
    font-optical-sizing: auto;
    font-kerning: normal;
    font-variant-numeric: proportional-nums;
    -webkit-font-smoothing: antialiased;
    scrollbar-color: var(--isobath) transparent;
  }

  body {
    margin: 0;
    min-height: 100dvh;
    font-size: var(--step-0);
    background: var(--sea);
    color: var(--ink);
    transition: background-color var(--dur-voyage) var(--ease-drift);
  }

  h1,
  h2,
  h3,
  h4,
  p,
  figure,
  blockquote,
  dl,
  dd,
  ol,
  ul {
    margin: 0;
  }

  h1,
  h2,
  h3,
  h4 {
    font-weight: 600;
    line-height: var(--leading-tight);
    text-wrap: balance;
  }

  p {
    text-wrap: pretty;
  }

  img,
  svg,
  video,
  canvas {
    display: block;
    max-width: 100%;
  }

  button,
  input,
  select,
  textarea {
    font: inherit;
    color: inherit;
    letter-spacing: inherit;
  }

  button {
    cursor: pointer;
  }

  a {
    color: inherit;
    text-decoration-thickness: 1px;
    text-underline-offset: 0.2em;
  }

  :focus-visible {
    outline: var(--focus-ring);
    outline-offset: var(--focus-offset);
  }

  ::selection {
    background: var(--magenta-wash);
  }

  kbd {
    display: inline-block;
    min-width: 1.6em;
    padding: 0.05em 0.4em;
    border-radius: 4px;
    font-family: var(--font-code);
    font-size: 0.82em;
    line-height: 1.5;
    text-align: center;
    background: var(--ink-wash);
    box-shadow: inset 0 -1px 0 var(--isobath);
  }

  .atl-visually-hidden {
    position: absolute !important;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  @media (prefers-reduced-motion: reduce) {
    :root:not([data-motion='full']) *,
    :root:not([data-motion='full']) *::before,
    :root:not([data-motion='full']) *::after {
      scroll-behavior: auto !important;
    }
  }
}
